{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R01-01",
   "status": "OK",
   "label": "청소년 고객 가입 대상",
   "source": {
    "quote": "만 19세 미만 실명의 개인"
   },
   "condition": {
    "==": [
     {
      "var": "customer.is_youth"
     },
     true
    ]
   },
   "effect": {
    "type": "REQUIRE",
    "value": "REAL_NAME"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R01-02",
   "status": "OK",
   "label": "개인사업자 및 임의단체 가입 제한",
   "source": {
    "quote": "개인사업자 및 서류미제출 임의단체, 공동명의 가입 불가"
   },
   "condition": {
    "in": [
     {
      "var": "customer.type"
     },
     [
      "INDIVIDUAL_BUSINESS",
      "UNREGISTERED_ORGANIZATION",
      "JOINT_ACCOUNT"
     ]
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R01-03",
   "status": "OK",
   "label": "1인 1계좌 제한",
   "source": {
    "quote": "「KB Young Youth 청소년통장」을 포함하여 1인 1계좌"
   },
   "condition": {
    "exists": {
     "event": "ACCOUNT_OPENING",
     "within": {
      "ref": "$customer"
     }
    }
   },
   "effect": {
    "type": "LIMIT_AMOUNT",
    "value": 1
   }
  }
 ]
}

