raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R04-01",
   "status": "OK",
   "label": "자동전환 조건",
   "source": {
    "quote": "매년 첫 영업일에 가입자의 연령이 만 19세인 경우 「KB국민ONE통장」으로 자동전환"
   },
   "let": {
    "switch_window": {
     "year_range": {
      "from": {
       "anchor": "contract.switch_date",
       "offset_years": 0
      },
      "to": {
       "anchor": "contract.switch_date",
       "offset_years": 0
      }
     }
    }
   },
   "condition": {
    "==": [
     {
      "var": "customer.age"
     },
     19
    ]
   },
   "effect": {
    "type": "REQUIRE",
    "value": "PRODUCT_SWITCH"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R04-02",
   "status": "OK",
   "label": "자동전환 대상 변경",
   "source": {
    "quote": "KB국민ONE통장을 이미 보유하고 있는 경우에는 「KB종합통장」으로 자동전환"
   },
   "guard": {
    "==": [
     {
      "var": "customer.has_product"
     },
     "KB국민ONE통장"
    ]
   },
   "condition": {
    "exists": {
     "event": "PRODUCT_SWITCH",
     "within": {
      "ref": "$switch_window"
     }
    }
   },
   "effect": {
    "type": "REQUIRE",
    "value": "KB종합통장"
   }
  }
 ]
}

