raw_first:
{
 "rules": [
  {
   "rule_id": "R-KBYY-S2-R08-01",
   "status": "OK",
   "label": "이자 지급시기",
   "source": {
    "quote": "매년 2월, 5월, 8월, 11월의 둘째 금요일에 결산하여 다음날 원금에 더함"
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "month": {
         "anchor": "contract.start_date",
         "offset_months": "0"
        }
       },
       [
        2,
        5,
        8,
        11
       ]
      ]
     },
     {
      "not": {
       "in": [
        {
         "var": "contract.termination_type"
        },
        [
         "EARLY",
         "PARTIAL",
         "MID_TERM",
         "NONE"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  },
  {
   "rule_id": "R-KBYY-S2-R08-02",
   "status": "OK",
   "label": "이자 계산시기 변경",
   "source": {
    "quote": "최종거래일로부터 5년이 경과한 날부터는 이자에 원금을 더하지 않고, 계좌해지 또는 추가 입출금 거래 발생일에 일괄 계산하여 지급할 수 있습니다"
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "duration_months": {
         "from": {
          "anchor": "contract.start_date",
          "offset_months": "0"
         },
         "to": {
          "anchor": "contract.last_transaction_date",
          "offset_months": "0"
         }
        }
       },
       60
      ]
     },
     {
      "in": [
       {
        "var": "contract.termination_type"
       },
       [
        "MATURITY",
        "EARLY",
        "PARTIAL",
        "MID_TERM",
        "NONE"
       ]
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_SUBTRACT",
    "value": 100,
    "unit": "%p",
    "applies_to": "BASE_RATE"
   }
  }
 ]
}

