   "rule_id": "R-KBYY-S2-R09-02",
   "status": "OK",
   "label": "특별금리 적용",
   "source": {
    "quote": "특별금리 : 저금통 설정일(또는 지난 원가일)부터 저금통 해제일(또는 원가일)전날까지를 이자계산 기간으로 하고, 매일의 저금통 잔액에 대해 결산일 현재 지점에 고시한 특별금리로 계산함"
   },
   "condition": {
    "in": [
     {
      "var": "contract.product_type"
     },
     "SAVING"
    ]
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": "SPECIAL_RATE",
    "unit": "%p",
    "applies_to": "SPECIAL_RATE"
   }
  }
 ]
}

