     }
    ]
   },
   "effect": {
    "type": "LIMIT_AMOUNT",
    "value": 1000000
   }
  },
  {
   "rule_id": "R-KBYY-S2-R23-03",
   "status": "OK",
   "label": "전환계좌 금리 적용",
   "source": {
    "quote": "전환계좌의 경우 전환 후 최초 결산기(지난 결산일부터 결산일 전일까지)에 대해서는 전환 전(前) 예금의 금리를 적용하고, 다음 결산기부터 전환된 예금의 금리를 적용합니다."
   },
   "let": {
    "previous_interest_rate": {
      "ref": "contract.previous_interest_rate"
    },
    "new_interest_rate": {
      "ref": "contract.new_interest_rate"
    }
   },
   "condition": {
    "and": [
     {
      "var": "contract.is_switched_account"
     },
     {
      "var": "contract.is_first_settlement"
     }
    ]
   },
   "effect": {
    "type": "RATE_OVERRIDE",
    "value": {
      "ref": "$previous_interest_rate"
    }
   }
  },
  {
   "rule_id": "R-KBYY-S2-R23-04",
   "status": "OK",
   "label": "재전환 제한",
   "source": {
    "quote": "이 통장에서 다른 통장으로의 전환 시 다음 결산일(매년 2월, 5월, 8월, 11월의 둘째 금요일)까지는 이 통장으로 재전환이 불가합니다."
   },
   "let": {
    "reconversion_date": {
      "month": "2,5,8,11",
      "day": "2",
      "weekday": "Friday"
    }
   },
   "condition": {
    "and": [
     {
      "var": "contract.is_switched_account"
     },
     {
      "var": "contract.is_reconversion_allowed"
     }
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  }
 ]
}

